//! Native conditional ownership across continuation escapes.

use super::powershell::run_clean;

fn assert_conditional(source: &str, elseifs: usize, assigned: bool) {
    let analysis = run_clean(source);
    assert!(
        analysis
            .facts
            .calls
            .iter()
            .all(|call| !matches!(call.callee, "else" | "elseif")),
        "{source:?}"
    );
    let language: tree_sitter::Language = tree_sitter_powershell::LANGUAGE.into();
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(&language).expect("powershell language loads");
    let tree = parser.parse(source, None).expect("parser returns a tree");
    let mut stack = vec![tree.root_node()];
    let mut conditionals = Vec::new();
    let mut assignments = Vec::new();
    while let Some(node) = stack.pop() {
        if node.kind() == "if_statement" {
            conditionals.push(node);
        } else if node.kind() == "assignment_expression" {
            assignments.push(node);
        }
        let mut cursor = node.walk();
        stack.extend(node.named_children(&mut cursor));
    }
    assert_eq!(conditionals.len(), 1, "{source:?}");
    let conditional = conditionals[0];
    assert!(conditional.child_by_field_name("else_clause").is_some(), "{source:?}");
    let actual = conditional
        .child_by_field_name("elseif_clauses")
        .map_or(0, |clauses| {
            let mut cursor = clauses.walk();
            clauses
                .named_children(&mut cursor)
                .filter(|node| node.kind() == "elseif_clause")
                .count()
        });
    assert_eq!(actual, elseifs, "{source:?}");
    if assigned {
        assert_eq!(assignments.len(), 1, "{source:?}");
        let value = assignments[0]
            .child_by_field_name("value")
            .expect("conditional assignment has a value");
        assert_eq!(value.id(), conditional.id(), "{source:?}");
    } else {
        assert!(assignments.is_empty(), "{source:?}");
    }
}

#[test]
fn escaped_lines_keep_conditional_values_and_branches_together() {
    for (ending_name, ending) in [("lf", "\n"), ("crlf", "\r\n")] {
        for (gap_name, gap) in [
            ("one", format!("{ending}`{ending}")),
            ("comment", format!("{ending}# note{ending}`{ending}")),
            ("indented", format!("{ending}  `{ending}")),
            ("two", format!("{ending}`{ending}`{ending}")),
        ] {
            for (tail_name, tail, elseifs) in [
                ("else", "else { 0 }", 0),
                ("elseif", "elseif ($false) { 2 } else { 0 }", 1),
            ] {
                for (context, prefix, suffix, assigned) in [
                    ("standalone", "", "", false),
                    ("assignment", "$result = ", "", true),
                    ("parenthesized-assignment", "($result = ", ")", true),
                    ("subexpression", "$(", ")", false),
                    ("hashtable-value", "@{ value = ", "\n}", false),
                    ("script-block", "{ $result = ", "\n}", true),
                ] {
                    let suffix = suffix.replace('\n', ending);
                    let source = format!("{prefix}if ($true) {{ 1 }}{gap}{tail}{suffix}{ending}");
                    assert_conditional(&source, elseifs, assigned);
                    println!("NATIVE_BRANCH_CASE branch-{ending_name}-{gap_name}-{tail_name}-{context}");
                }
            }
        }
    }
}

//! Format marks are literal native argument text after one or two dashes.

use sloplint_core::facts::ArgShape;
use super::powershell::{call, run_clean};

fn assert_word(source: &str, word: &str, dynamic: bool) {
    let analysis = run_clean(source);
    let call = call(&analysis, "Capture-Native");
    assert_eq!(call.args.len(), 1, "{source:?}");
    if dynamic {
        assert!(matches!(call.args[0].shape, ArgShape::Concat { .. }), "{source:?}");
    } else {
        assert!(matches!(call.args[0].shape, ArgShape::Str { .. }), "{source:?}");
    }
    let language: tree_sitter::Language = tree_sitter_powershell::LANGUAGE.into();
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(&language).expect("powershell language loads");
    let tree = parser.parse(source, None).expect("parser returns a tree");
    let mut stack = vec![tree.root_node()];
    let mut spans = Vec::new();
    while let Some(node) = stack.pop() {
        if node.kind() == "generic_token" {
            spans.push(node.utf8_text(source.as_bytes()).expect("source is UTF-8"));
        }
        let mut cursor = node.walk();
        stack.extend(node.named_children(&mut cursor));
    }
    assert_eq!(spans, [word], "{source:?}");
}

#[test]
fn format_mark_dash_words_keep_native_counts_and_complete_extents() {
    for mark in ['\u{200b}', '\u{feff}', '\u{2060}'] {
        for dashes in ["-", "--"] {
            for (kind, suffix, dynamic) in [
                ("empty", "", false),
                ("tail", "tail", false),
                ("double-quoted", "\"two words\"", false),
                ("single-quoted", "'two words'", false),
                ("escaped-space", "` tail", false),
                ("escaped-dollar", "`$tail", false),
                ("variable", "$tail", true),
            ] {
                let word = format!("{dashes}{mark}{suffix}");
                let prelude = if dynamic { "$tail = 'value'\n" } else { "" };
                let source = format!("{prelude}Capture-Native {word}\n");
                assert_word(&source, &word, dynamic);
                println!("NATIVE_DASH_CASE dash-{:04x}-{}-{kind} 1", u32::from(mark), dashes.len());
            }
        }
    }
}

#[test]
fn quoted_format_mark_dash_words_remain_single_arguments() {
    for mark in ['\u{200b}', '\u{feff}', '\u{2060}'] {
        for dashes in ["-", "--"] {
            for quote in ['\'', '"'] {
                let source = format!("Capture-Native {quote}{dashes}{mark}{quote}\n");
                let analysis = run_clean(&source);
                let call = call(&analysis, "Capture-Native");
                assert_eq!(call.args.len(), 1, "{source:?}");
                assert!(matches!(call.args[0].shape, ArgShape::Str { .. }), "{source:?}");
            }
        }
    }
}

//! Keep the published custom-query contract for legacy separator tokens.

use sloplint_core::{Confidence, CustomRuleSpec, Severity};
use sloplint_core::lang::Lang;
use sloplint_core::role::CodeRole;
use sloplint_syntax::{CustomRules, FileInput, Parsers, analyze};

#[test]
fn legacy_separator_queries_compile_and_capture_exact_character_extents() {
    for separator in [' ', '\t', '\u{a0}'] {
        let spec = CustomRuleSpec {
            id: "custom/separator".to_owned(),
            language: "powershell".to_owned(),
            severity: Severity::Info,
            confidence: Confidence::High,
            message: "Separator {match}".to_owned(),
            why: "Keep the existing anonymous token query contract.".to_owned(),
            fix: "Inspect the captured separator.".to_owned(),
            query: format!("\"{separator}\" @match"),
            include: Vec::new(),
            exclude: Vec::new(),
        };
        let rules = CustomRules::compile(&[spec]).expect("legacy separator query compiles");
        for gap in [" ", "\t", "\u{a0}", "  ", "\t\t", "\u{a0}\u{a0}", " \t\u{a0} ", "\u{a0}\t "] {
            let source = format!("Capture-Native{gap}hello{gap}world\n");
            let input = FileInput {
                lang: Lang::PowerShell,
                path: "legacy.ps1",
                source: &source,
                role: CodeRole::Library,
            };
            let analysis = analyze(&mut Parsers::new(), &input, &rules);
            assert!(analysis.parse_error.is_none(), "{source:?}");
            assert!(!analysis.timed_out && analysis.custom_capped.is_empty());
            let actual: Vec<_> = analysis.custom_hits.iter().map(|hit| {
                let captured = hit.captures.iter().find(|(name, _)| *name == "match")
                    .expect("query returns its match capture").1;
                (hit.pos.byte, captured)
            }).collect();
            let expected: Vec<_> = source.char_indices().filter(|(_, character)| *character == separator).map(|(start, character)| (
                u32::try_from(start).expect("small fixture offset"),
                source.get(start..start + character.len_utf8()).expect("character boundary")
            )).collect();
            assert_eq!(actual, expected, "{source:?}, U+{:04X}", u32::from(separator));
            println!("LEGACY_SEPARATOR_QUERY U+{:04X} {:?} {:?}", u32::from(separator), gap, actual);
        }
    }
}
